import { useEffect, useState } from "react";
import "./StatusMessage.css";

export interface StatusMessageProps {
  text: string;
  onDismiss: () => void;
}

export function StatusMessage({ text, onDismiss }: StatusMessageProps) {
  // Screen readers reliably announce text inserted into a live region that
  // already exists in the DOM. Mount the empty region first, then fill it on
  // the next frame so the message is announced.
  const [ready, setReady] = useState(false);

  useEffect(() => {
    const frame = window.requestAnimationFrame(() => setReady(true));
    return () => window.cancelAnimationFrame(frame);
  }, []);

  // Escape dismisses the message from anywhere on the page.
  useEffect(() => {
    const onKeyDown = (event: KeyboardEvent) => {
      if (event.key === "Escape") {
        onDismiss();
      }
    };
    window.addEventListener("keydown", onKeyDown);
    return () => window.removeEventListener("keydown", onKeyDown);
  }, [onDismiss]);

  return (
    <div
      className="status-message"
      role="status"
      aria-live="polite"
      aria-atomic="true"
    >
      <p className="status-message__text">{ready ? text : ""}</p>
      <button
        type="button"
        className="status-message__dismiss"
        onClick={onDismiss}
      >
        Dismiss
      </button>
    </div>
  );
}
