  --status-message-fg: #2e2a24;
  --status-message-border: #d8d1c2;
  --status-message-shadow: 0 6px 20px rgba(46, 42, 36, 0.12);
  --status-message-button-bg: #e7e1d3;
  --status-message-button-fg: #2e2a24;
  --status-message-button-hover: #dcd4c2;
  --status-message-focus: #3b6e8f;
}

/* Night theme */
[data-theme="night"] {
  --status-message-bg: #1f2227;
  --status-message-fg: #e6e2da;
  --status-message-border: #3a3f47;
  --status-message-shadow: 0 6px 20px rgba(0, 0, 0, 0.45);
  --status-message-button-bg: #2c3138;
  --status-message-button-fg: #e6e2da;
  --status-message-button-hover: #383e47;
  --status-message-focus: #8fb8d4;
}

.status-message {
  position: fixed;
  left: 50%;
  bottom: 1.5rem;
  transform: translateX(-50%);
  z-index: 1000;

  display: flex;
  align-items: center;
  gap: 1rem;
  max-width: min(90vw, 36rem);
  padding: 0.75rem 1rem 0.75rem 1.25rem;

  background: var(--status-message-bg);
  color: var(--status-message-fg);
  border: 1px solid var(--status-message-border);
  border-radius: 0.75rem;
  box-shadow: var(--status-message-shadow);

  font-family: inherit;
  font-size: 0.95rem;
  line-height: 1.4;

  animation: status-message-in 220ms ease-out both;
}

.status-message__text {
  margin: 0;
  flex: 1 1 auto;
  min-width: 0;
  overflow-wrap: anywhere;
}

.status-message__dismiss {
  flex: 0 0 auto;
  padding: 0.4rem 0.9rem;

  font: inherit;
  font-weight: 600;
  color: var(--status-message-button-fg);
  background: var(--status-message-button-bg);
  border: 1px solid var(--status-message-border);
  border-radius: 0.5rem;
  cursor: pointer;

  transition: background-color 120ms ease;
}

.status-message__dismiss:hover {
  background: var(--status-message-button-hover);
}

.status-message__dismiss:focus-visible {
  outline: 2px solid var(--status-message-focus);
  outline-offset: 2px;
}

@keyframes status-message-in {
  from {
    opacity: 0;
    transform: translate(-50%, 0.5rem);
  }
  to {
    opacity: 1;
    transform: translate(-50%, 0);
  }
}

@media (prefers-reduced-motion: reduce) {
  .status-message {
    animation: none;
  }

  .status-message__dismiss {
    transition: none;
  }
}
